/* Strict display rule for hidden attribute */
[hidden] {
  display: none !important;
}

:root {
  --bg-primary: #1e1b2e;
  --bg-card: #2a2540;
  --bg-card-inner: #161324;
  --color-gold: #f4c430;
  --color-gold-hover: #ffda66;
  --color-cream: #fbf7ee;
  --color-red-error: #ff4757;
  --color-border: #443c68;
  --color-shadow: #0e0c17;
  --font-family: 'Courier New', Courier, monospace, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: var(--bg-primary);
  /* Pixel grid pattern */
  background-image: 
    linear-gradient(rgba(255, 255, 255, 0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.03) 1px, transparent 1px);
  background-size: 16px 16px;
  color: var(--color-cream);
  font-family: var(--font-family);
  font-size: 16px;
  line-height: 1.5;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 20px 12px;
}

.converter-card {
  width: 100%;
  max-width: 520px;
  background-color: var(--bg-card);
  border: 4px solid var(--color-gold);
  box-shadow: 6px 6px 0px var(--color-shadow);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.card-header {
  text-align: center;
  border-bottom: 3px dashed var(--color-border);
  padding-bottom: 16px;
}

.pixel-icon {
  font-size: 2rem;
  margin-bottom: 6px;
}

.title {
  font-size: 1.75rem;
  font-weight: 800;
  color: var(--color-gold);
  letter-spacing: 2px;
  text-transform: uppercase;
  text-shadow: 2px 2px 0px var(--color-shadow);
}

.subtitle {
  font-size: 0.85rem;
  color: var(--color-cream);
  opacity: 0.8;
  margin-top: 4px;
}

.converter-section {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.converter-block {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.pixel-label {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--color-gold);
  letter-spacing: 0.5px;
}

.input-wrapper {
  display: flex;
  gap: 8px;
}

.pixel-input {
  flex: 1;
  background-color: var(--bg-card-inner);
  border: 3px solid var(--color-border);
  color: var(--color-cream);
  font-family: inherit;
  font-size: 1.1rem;
  font-weight: bold;
  padding: 10px 12px;
  outline: none;
  box-shadow: inset 2px 2px 0px var(--color-shadow);
  transition: border-color 0.1s, box-shadow 0.1s;
}

.pixel-input:hover {
  border-color: var(--color-gold-hover);
}

.pixel-input:focus {
  border-color: var(--color-gold);
  box-shadow: 0 0 0 2px var(--color-gold);
}

.pixel-btn {
  background-color: var(--color-gold);
  color: var(--bg-primary);
  font-family: inherit;
  font-size: 0.9rem;
  font-weight: 900;
  padding: 0 14px;
  border: 3px solid var(--color-gold);
  cursor: pointer;
  box-shadow: 2px 2px 0px var(--color-shadow);
  outline: none;
}

.pixel-btn:hover {
  background-color: var(--color-gold-hover);
  border-color: var(--color-gold-hover);
}

.pixel-btn:focus {
  outline: 2px solid var(--color-cream);
}

.pixel-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 0px 0px 0px var(--color-shadow);
}

.output-box {
  background-color: var(--bg-card-inner);
  border: 2px solid var(--color-border);
  padding: 10px 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 48px;
  flex-wrap: wrap;
  gap: 8px;
}

.output-caption {
  font-size: 0.85rem;
  color: var(--color-cream);
  opacity: 0.7;
}

.output-value {
  font-size: 1.2rem;
  font-weight: bold;
  color: var(--color-gold);
  word-break: break-all;
}

.output-value.invalid {
  color: var(--color-red-error);
  font-style: normal;
}

.divider-strip {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin: 2px 0;
}

.pixel-dot {
  width: 8px;
  height: 8px;
  background-color: var(--color-gold);
  box-shadow: 1px 1px 0px var(--color-shadow);
}

.card-footer {
  border-top: 3px dashed var(--color-border);
  padding-top: 14px;
}

.quick-cheatsheet {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  justify-content: center;
}

.chip {
  background-color: var(--bg-card-inner);
  border: 1px solid var(--color-border);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 8px;
  color: var(--color-cream);
}

/* Responsive adjustments for 360px+ screens */
@media (max-width: 420px) {
  .converter-card {
    padding: 16px;
  }
  .title {
    font-size: 1.4rem;
  }
  .output-box {
    flex-direction: column;
    align-items: flex-start;
  }
}

(function () {
  'use strict';

  // Mapping of Roman numerals for standard subtractive notation
  const ROMAN_MAPPING = [
    { val: 1000, sym: 'M' },
    { val: 900,  sym: 'CM' },
    { val: 500,  sym: 'D' },
    { val: 400,  sym: 'CD' },
    { val: 100,  sym: 'C' },
    { val: 90,   sym: 'XC' },
    { val: 50,   sym: 'L' },
    { val: 40,   sym: 'XL' },
    { val: 10,   sym: 'X' },
    { val: 9,    sym: 'IX' },
    { val: 5,    sym: 'V' },
    { val: 4,    sym: 'IV' },
    { val: 1,    sym: 'I' }
  ];

  // Strict standard Roman numeral regex matching 1 to 3999
  const STRICT_ROMAN_REGEX = /^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$/;

  // Convert Integer to Roman (1 - 3999)
  function intToRoman(num) {
    if (isNaN(num) || num < 1 || num > 3999 || !Number.isInteger(num)) {
      return null;
    }
    let remainder = num;
    let result = '';
    for (let i = 0; i < ROMAN_MAPPING.length; i++) {
      const item = ROMAN_MAPPING[i];
      while (remainder >= item.val) {
        result += item.sym;
        remainder -= item.val;
      }
    }
    return result;
  }

  // Convert Roman to Integer (1 - 3999)
  function romanToInt(roman) {
    if (!roman || typeof roman !== 'string') {
      return null;
    }
    const clean = roman.trim().toUpperCase();
    if (clean === '' || !STRICT_ROMAN_REGEX.test(clean)) {
      return null;
    }

    const romanCharValues = {
      I: 1, V: 5, X: 10, L: 50,
      C: 100, D: 500, M: 1000
    };

    let sum = 0;
    for (let i = 0; i < clean.length; i++) {
      const curr = romanCharValues[clean[i]];
      const next = (i + 1 < clean.length) ? romanCharValues[clean[i + 1]] : 0;
      if (curr < next) {
        sum -= curr;
      } else {
        sum += curr;
      }
    }

    if (sum < 1 || sum > 3999) {
      return null;
    }
    return sum;
  }

  // DOM Elements
  const numberInput = document.getElementById('number-input');
  const romanOutput = document.getElementById('roman-output');
  const romanInput = document.getElementById('roman-input');
  const numberOutput = document.getElementById('number-output');
  const clearNumBtn = document.getElementById('clear-num-btn');
  const clearRomanBtn = document.getElementById('clear-roman-btn');

  // Updates Number to Roman display
  function updateNumberToRoman() {
    const rawVal = numberInput.value.trim();
    if (rawVal === '') {
      romanOutput.textContent = '---';
      romanOutput.classList.remove('invalid');
      return;
    }

    const num = Number(rawVal);
    const result = intToRoman(num);
    if (result === null) {
      romanOutput.textContent = 'Not valid';
      romanOutput.classList.add('invalid');
    } else {
      romanOutput.textContent = result;
      romanOutput.classList.remove('invalid');
    }
  }

  // Updates Roman to Number display
  function updateRomanToNumber() {
    const rawVal = romanInput.value.trim();
    if (rawVal === '') {
      numberOutput.textContent = '---';
      numberOutput.classList.remove('invalid');
      return;
    }

    const result = romanToInt(rawVal);
    if (result === null) {
      numberOutput.textContent = 'Not valid';
      numberOutput.classList.add('invalid');
    } else {
      numberOutput.textContent = String(result);
      numberOutput.classList.remove('invalid');
    }
  }

  // Event Listeners
  numberInput.addEventListener('input', updateNumberToRoman);
  romanInput.addEventListener('input', updateRomanToNumber);

  clearNumBtn.addEventListener('click', function () {
    numberInput.value = '';
    updateNumberToRoman();
    numberInput.focus();
  });

  clearRomanBtn.addEventListener('click', function () {
    romanInput.value = '';
    updateRomanToNumber();
    romanInput.focus();
  });
})();
